(function(){'use strict';
const copy=x=>JSON.parse(JSON.stringify(x)),esc=x=>String(x).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const C={ink:'#163d55',active:'#087f8c',light:'#e5f5f2',muted:'#79939e',warm:'#bb7831'};
function text(x,y,s,cls='rc-math',anchor='start'){return `<text x="${x}" y="${y}" class="${cls}" text-anchor="${anchor}">${esc(s)}</text>`;}
function rect(x,y,w,h,fill=C.light){return `<rect x="${x}" y="${y}" width="${w}" height="${h}" rx="8" fill="${fill}" stroke="${C.muted}"/>`;}
function line(points,color=C.active,arrow=false){return `<polyline points="${points.map(p=>p.join(',')).join(' ')}" fill="none" stroke="${color}" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"${arrow?' marker-end="url(#rc-arrow)"':''}/>`;}
function svg(body,h=340){return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 760 ${h}" role="img"><defs><marker id="rc-arrow" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="7" markerHeight="7" orient="auto"><path d="M1 1 L9 5 L1 9" fill="none" stroke="${C.active}" stroke-width="1.5"/></marker></defs>${body}</svg>`;}
const fact=n=>{let v=1;for(let j=2;j<=n;j++)v*=j;return v;};
function binom(n,k){if(k<0||k>n)return 0;let v=1;for(let j=1;j<=Math.min(k,n-k);j++)v=v*(n-j+1)/j;return v;}
function derangements(n){let a=[1,0];for(let j=2;j<=n;j++)a[j]=(j-1)*(a[j-1]+a[j-2]);return a.slice(0,n+1);}
function stirling(n){const a=Array.from({length:n+1},()=>Array(n+1).fill(0));a[0][0]=1;for(let i=1;i<=n;i++)for(let k=1;k<=i;k++)a[i][k]=a[i-1][k-1]+k*a[i-1][k];return a;}
function tilings(n){if(n===0)return[[]];const out=[];function rec(left,c,tiles){if(!left){out.push(tiles);return;}rec(left-1,c+1,[...tiles,{c,row:0,w:1,h:2}]);if(left>=2)rec(left-2,c+2,[...tiles,{c,row:0,w:2,h:1},{c,row:1,w:2,h:1}]);}rec(n,0,[]);return out;}
function integerPartitions(n,k,max=n){if(n===0&&k===0)return[[]];if(n<0||k<=0)return[];let out=[];for(let x=Math.min(max,n);x>=1;x--)for(const t of integerPartitions(n-x,k-1,x))out.push([x,...t]);return out;}
function dyck(n){let out=[];function rec(u,d,s){if(u===n&&d===n){out.push(s);return;}if(u<n)rec(u+1,d,s+'U');if(d<u)rec(u,d+1,s+'D');}rec(0,0,'');return out;}
function validate(raw){const s={operation:'tiling',n:4,p:2,a0:0,modulus:3,...copy(raw)};if(!['unrolling','differences','boundary','tiling','resonance','automaton','derangements','partitions','ferrers','catalan','modular','matrix','conjugate','reflection'].includes(s.operation))throw Error('Unknown recurrence model.');if(!Number.isInteger(s.n)||s.n<1||s.n>8)throw Error('The index must be an integer from one through eight.');if(s.operation==='catalan'&&s.n>4)throw Error('Complete path enumeration supports at most four pairs.');if(['ferrers','conjugate'].includes(s.operation)&&s.n<3)throw Error('Exactly-three-part diagrams require a total of at least three.');if(!Number.isInteger(s.p)||Math.abs(s.p)>4||!Number.isInteger(s.a0)||Math.abs(s.a0)>10)throw Error('The multiplier and starting value must be small integers.');if(!Number.isInteger(s.modulus)||s.modulus<2||s.modulus>8)throw Error('The modulus must be an integer from two through eight.');return s;}
function evaluate(raw){const s=validate(raw),n=s.n;let states=[],result;
 if(s.operation==='unrolling'){let terms=[];for(let j=1;j<=n;j++)terms.push({j,injected:j,weight:s.p**(n-j),value:j*s.p**(n-j)});let sum=s.a0*s.p**n;states.push({step:0,terms:[],sum,base:sum});for(const t of terms){sum+=t.value;states.push({step:t.j,terms:terms.filter(x=>x.j<=t.j),sum,base:s.a0*s.p**n});}result={value:sum,terms};}
 else if(s.operation==='differences'){const rows=[Array.from({length:n+1},(_,i)=>(i+1)**2)];while(rows.at(-1).length>1)rows.push(rows.at(-1).slice(1).map((x,i)=>x-rows.at(-1)[i]));states=rows.slice(0,Math.min(4,rows.length)).map((_,i)=>({step:i,rows:rows.slice(0,i+1)}));result={rows,thirdDifference:rows.length>3?rows[3]:[]};}
 else if(s.operation==='boundary'){const a=Array.from({length:n+1},(_,i)=>i===0?4:i===1?5:6*2**(i-2));states=a.map((_,i)=>({step:i,values:a.slice(0,i+1)}));result={values:a};}
 else if(s.operation==='tiling'){const all=tilings(n);states=[{step:0,tiles:[],case:'Empty board before enumeration'},...all.map((tiles,i)=>({step:i+1,tiles,case:tiles[0].h===2?'First-column vertical case':'First-two-columns horizontal case'}))];result={count:all.length,vertical:all.filter(t=>t[0].h===2).length,horizontal:all.filter(t=>t[0].h!==2).length};}
 else if(s.operation==='resonance'){const u=Array.from({length:n+1},(_,i)=>i*(i-1)/2);states=u.map((_,i)=>({step:i,values:u.slice(0,i+1),value:u[i]*2**i,residual:i>=2?u[i]-2*u[i-1]+u[i-2]:null}));result={normalized:u,values:u.map((v,i)=>v*2**i)};}
 else if(s.operation==='automaton'){let u=1,v=1;states=[{step:1,u,v,total:3}];for(let i=2;i<=n;i++){[u,v]=[u+v,2*u+v];states.push({step:i,u,v,total:2*u+v});}result={u,v,total:2*u+v};}
 else if(s.operation==='derangements'){const a=derangements(n);states=a.map((v,i)=>({step:i,value:v,two:i>=2?(i-1)*a[i-2]:null,long:i>=2?(i-1)*a[i-1]:null}));result={values:a,count:a[n]};}
 else if(s.operation==='partitions'){const a=stirling(n);states=Array.from({length:n+1},(_,i)=>({step:i,row:a[i].slice(0,i+1),bell:a[i].reduce((v,x)=>v+x,0)}));result={rows:a,bell:states.at(-1).bell};}
 else if(s.operation==='ferrers'){const all=integerPartitions(n,3);states=all.map((parts,i)=>({step:i+1,parts,case:parts.at(-1)===1?'Remove a part equal to one':'Subtract one from every part'}));result={count:all.length,withOne:all.filter(x=>x.at(-1)===1).length,withoutOne:all.filter(x=>x.at(-1)>1).length};}
 else if(s.operation==='catalan'){const all=dyck(n);states=[{step:0,path:'',split:null},...all.map((path,i)=>{let h=0,split=0;for(let j=0;j<path.length;j++){h+=path[j]==='U'?1:-1;if(h===0){split=j+1;break;}}return{step:i+1,path,split};})];result={count:all.length};}
 else if(s.operation==='conjugate'){const original=[n-2,1,1],transposed=Array.from({length:n-2},(_,i)=>original.filter(x=>x>i).length);states=[{step:0,original,transposed:[]},{step:1,original,transposed}];result={original,transposed,total:n};}
 else if(s.operation==='reflection'){const original='DUUDUDUDUDUD';let h=0,first=0;for(let j=0;j<original.length;j++){h+=original[j]==='U'?1:-1;if(h<0){first=j+1;break;}}const transformed=original.slice(0,first).split('').map(c=>c==='U'?'D':'U').join('')+original.slice(first);states=[{step:0,path:original,first},{step:1,path:transformed,first}];result={original,transformed,first,endpoint:2};}
 else if(s.operation==='modular'){let u=0,v=1;const seen=new Map();while(!seen.has(u+','+v)){seen.set(u+','+v,states.length);states.push({step:states.length,u,v});[u,v]=[v,(u+v)%s.modulus];if(states.length>100)throw Error('Cycle exceeds the declared trace bound.');}states.push({step:states.length,u,v,returnTo:seen.get(u+','+v)});result={period:states.length-1,returnTo:seen.get(u+','+v),residue:states[s.n%(states.length-1)].u};}
 else {let a=5,b=2;states=[{step:1,a,b}];for(let i=2;i<=n;i++){[a,b]=[5*a-6*b,a];states.push({step:i,a,b});}result={a,b};}
 return{spec:s,states,result};}
function seriesCells(values,label){let b=text(34,54,label,'rc-prose');const w=Math.min(72,680/values.length);values.forEach((v,i)=>{const x=40+i*w;b+=rect(x,106,w-8,64)+text(x+(w-8)/2,146,v,'rc-math','middle')+text(x+(w-8)/2,198,i,'rc-math','middle');});return b+text(34,236,'Index labels identify the declared starting point.','rc-prose');}
function draw(s,z,r){let b='';
 if(s.operation==='unrolling'){b+=text(34,44,'Earlier forcing contributions; bar heights show absolute magnitudes','rc-prose');const max=Math.max(1,...r.terms.map(t=>Math.abs(t.value)),Math.abs(z.base));r.terms.forEach((t,i)=>{const x=65+i*76;const shown=t.j<=z.step,h=shown?120*Math.abs(t.value)/max:0;b+=line([[x,220],[x,220-h]],shown?C.active:C.muted)+rect(x-18,220-h,36,Math.max(2,h),shown?C.light:'#f2f4f5')+text(x,252,'j='+t.j,'rc-math','middle');if(shown)b+=text(x,195-h,t.value,'rc-math','middle');});b+=text(34,300,'Propagated base = '+z.base+'; accumulated value = '+z.sum,'rc-math');}
 else if(s.operation==='differences'){b+=text(34,40,'Successive forward differences of (n + 1) squared','rc-prose');z.rows.forEach((row,j)=>row.forEach((v,i)=>{const x=45+i*65+j*32.5,y=74+j*60;b+=rect(x,y,52,42)+text(x+26,y+28,v,'rc-math','middle');if(j&&i<row.length)b+=line([[x+26,y-17],[x+26,y-4]],C.active,true);}));}
 else if(['boundary','resonance'].includes(s.operation)){b+=seriesCells(z.values,s.operation==='boundary'?'Independent prefix at indices zero and one; tail begins at two':'Normalized sequence after division by the exponential base power');b+=text(34,294,s.operation==='boundary'?'Updates before index three are not imposed.':'Exact term = '+z.value+'; second difference = '+(z.residual===null?'not yet defined':z.residual),'rc-prose');}
 else if(s.operation==='tiling'){const cell=48,ox=(760-s.n*cell)/2,oy=110;b+=text(34,46,z.step===0?'Enumerate every complete tiling once':z.case,'rc-prose');for(let c=0;c<s.n;c++)for(let row=0;row<2;row++)b+=`<rect x="${ox+c*cell}" y="${oy+row*cell}" width="48" height="48" fill="#f8fbfc" stroke="${C.muted}"/>`;z.tiles.forEach((t,i)=>{const x=ox+t.c*cell+4,y=oy+t.row*cell+4;b+=rect(x,y,t.w*cell-8,t.h*cell-8,i%2? '#f3e8d7':C.light);});b+=text(380,262,z.step+' of '+r.count+' complete tilings displayed','rc-prose','middle')+text(380,302,'Counts: vertical '+r.vertical+' + horizontal '+r.horizontal+' = '+r.count,'rc-math','middle');}
 else if(s.operation==='automaton'){const arc=d=>`<path d="${d}" fill="none" stroke="${C.active}" stroke-width="2" marker-end="url(#rc-arrow)"/>`;b+=text(34,40,'Length '+z.step+': restricted-ending state and unrestricted-ending state','rc-prose');b+=arc('M275 165 C350 115 410 115 485 165')+arc('M485 215 C410 275 350 275 275 215')+arc('M200 150 C140 65 320 65 260 150')+arc('M500 150 C440 65 620 65 560 150');b+=text(380,133,'2','rc-math','middle')+text(380,260,'1','rc-math','middle')+text(230,85,'1','rc-math','middle')+text(530,85,'1','rc-math','middle');for(const[x,label,value]of[[230,'u',z.u],[530,'v',z.v]])b+=`<circle cx="${x}" cy="190" r="50" fill="${C.light}" stroke="${C.active}"/>`+text(x,185,label,'rc-math','middle')+text(x,213,value,'rc-math','middle');b+=text(380,314,'Total = 2u + v = '+z.total,'rc-math','middle');}
 else if(s.operation==='derangements'){b+=text(34,42,'Size '+z.step+': two reversible cases after choosing the image of one','rc-prose');function cycle(mapping,ox,cy){const n=mapping.length,pts=Array.from({length:n},(_,i)=>[ox+94*Math.cos(-Math.PI/2+2*Math.PI*i/n),cy+58*Math.sin(-Math.PI/2+2*Math.PI*i/n)]);for(let i=0;i<n;i++){const a=pts[i],v=pts[mapping[i]-1],dx=v[0]-a[0],dy=v[1]-a[1],d=Math.hypot(dx,dy);if(!d)continue;const from=[a[0]+19*dx/d,a[1]+19*dy/d],to=[v[0]-20*dx/d,v[1]-20*dy/d];if(mapping[mapping[i]-1]===i+1){const mid=[(from[0]+to[0])/2-18*dy/d,(from[1]+to[1])/2+18*dx/d];b+=`<path d="M${from[0]} ${from[1]} Q${mid[0]} ${mid[1]} ${to[0]} ${to[1]}" fill="none" stroke="${C.active}" stroke-width="2" marker-end="url(#rc-arrow)"/>`;}else b+=line([from,to],C.active,true);}pts.forEach(([x,y],i)=>{b+=`<circle cx="${x}" cy="${y}" r="17" fill="${i===0?'#f3e8d7':C.light}" stroke="${C.active}"/>`+text(x,y+6,i+1,'rc-node','middle');});}if(z.step>=2){let two=Array.from({length:z.step},(_,i)=>i+2);two[0]=2;two[1]=1;if(z.step>=4){for(let i=2;i<z.step;i++)two[i]=i===z.step-1?3:i+2;cycle(two,200,185);}else if(z.step===2)cycle(two,200,185);else b+=text(200,180,'No valid leftover derangement','rc-prose','middle');if(z.step>=3){let long=Array.from({length:z.step},(_,i)=>i===z.step-1?1:i+2);cycle(long,555,185);}else b+=text(555,180,'No longer cycle at size two','rc-prose','middle');b+=text(200,90,'Two-cycle sample','rc-prose','middle')+text(555,90,'Longer-cycle sample','rc-prose','middle');}else b+=text(380,180,z.step===0?'One empty permutation':'No derangement on one element','rc-prose','middle');b+=text(380,286,z.step<2?'Boundary D = '+z.value:'All image choices: '+z.two+' + '+z.long+' = '+z.value,'rc-math','middle')+text(380,322,'Drawings are one representative per feasible case, not all permutations.','rc-prose','middle');}
 else if(s.operation==='partitions'){b+=text(34,44,'Stirling row for '+z.step+' elements; columns are block counts','rc-prose');z.row.forEach((v,k)=>{const x=40+k*72;b+=rect(x,110,60,56)+text(x+30,145,v,'rc-math','middle')+text(x+30,202,'k='+k,'rc-math','middle');});b+=text(34,270,'Bell count is the sum of this complete row: '+z.bell,'rc-prose');}
 else if(s.operation==='ferrers'){b+=text(34,44,'Partition '+z.parts.join(' + ')+': '+z.case,'rc-prose');const cell=32;z.parts.forEach((p,row)=>{for(let j=0;j<p;j++)b+=rect(55+j*cell,105+row*48,26,34,(z.case.startsWith('Subtract')?j===0:row===2)?'#f3e8d7':C.light);});const reduced=z.case.startsWith('Subtract')?z.parts.map(x=>x-1):z.parts.slice(0,-1);b+=line([[325,172],[408,172]],C.active,true);reduced.forEach((p,row)=>{for(let j=0;j<p;j++)b+=rect(445+j*cell,105+row*48,26,34);});b+=text(55,86,'Original','rc-prose')+text(445,86,'Reduced: '+reduced.join(' + '),'rc-prose')+text(34,305,'The operation is reversible; the complete original count is '+r.count,'rc-prose');}
 else if(s.operation==='catalan'){const cell=65,ox=80,base=265;let x=ox,y=base,points=[[x,y]],prefix=[[x,y]],suffix=[];b+=text(34,44,'A path stays at nonnegative height and ends at zero','rc-prose')+line([[60,base],[700,base]],C.muted);for(let i=0;i<z.path.length;i++){x+=cell;y+=z.path[i]==='U'?-40:40;points.push([x,y]);if(i<z.split)prefix.push([x,y]);else suffix.push([x,y]);}if(z.path)b+=line(prefix,C.warm)+line([prefix.at(-1),...suffix],C.active);for(const[x,y]of points)b+=`<circle cx="${x}" cy="${y}" r="4" fill="${C.ink}"/>`;b+=text(34,315,z.path?'First return at step '+z.split+'; enclosed size '+(z.split/2-1):'Empty path before enumerating '+r.count+' valid paths','rc-prose');}
 else if(s.operation==='conjugate'){b+=text(34,40,'Transpose the Ferrers diagram: every cell swaps row and column','rc-prose');function cells(parts,x){parts.forEach((count,row)=>{for(let j=0;j<count;j++)b+=rect(x+j*31,82+row*36,25,28);});}cells(z.original,65);if(z.step)cells(z.transposed,450);b+=line([[310,167],[408,167]],C.active,true)+text(65,66,z.original.join(' + '),'rc-math')+text(450,66,z.step?z.transposed.join(' + '):'Transpose next','rc-math')+text(34,320,'Cell count remains '+r.total+'; applying the operation twice restores the input.','rc-prose');}
 else if(s.operation==='reflection'){const ox=70,base=232,cell=50;let x=ox,y=base,pts=[[x,y]];b+=text(34,42,z.step?'Reflected prefix: seven up steps, five down steps':'Bad balanced path: first crossing below zero','rc-prose')+line([[50,base],[725,base]],C.muted);for(let j=0;j<z.path.length;j++){const old=[x,y];x+=cell;y+=z.path[j]==='U'?-32:32;b+=line([old,[x,y]],j<z.first?C.warm:C.active);pts.push([x,y]);}pts.forEach(([x,y])=>{b+=`<circle cx="${x}" cy="${y}" r="4" fill="${C.ink}"/>`;});b+=text(34,310,z.step?'Endpoint height two; reflect the first visit to height one to invert.':'Reflect through the first negative-one visit to construct the image.','rc-prose');}
 else if(s.operation==='modular'){b+=text(34,44,'Complete Fibonacci pair state modulo '+s.modulus,'rc-prose');const limit=10,start=Math.max(0,z.step-limit+1);const relevant=Array.from({length:z.step-start+1},(_,i)=>start+i);let u=0,v=1,pairs=[];for(let i=0;i<=z.step;i++){pairs.push([u,v]);[u,v]=[v,(u+v)%s.modulus];}relevant.forEach((i,j)=>{const x=34+j*70;b+=rect(x,106,58,70,i===z.step?C.light:'#f7fafb')+text(x+29,137,pairs[i][0],'rc-math','middle')+text(x+29,161,pairs[i][1],'rc-math','middle')+text(x+29,205,i,'rc-math','middle');if(j<relevant.length-1)b+=line([[x+59,140],[x+68,140]],C.active,true);});b+=text(34,275,z.returnTo!==undefined?'First state returns: cycle length '+r.period:'One complete pair determines the next pair.','rc-prose');}
 else {b+=text(34,42,'Exact companion update from two preceding values','rc-prose');b+=rect(55,114,190,105)+text(150,149,'Latest a = '+z.a,'rc-math','middle')+text(150,184,'Previous b = '+z.b,'rc-math','middle')+line([[245,165],[315,165]],C.active,true)+rect(326,114,170,105)+text(411,154,'5a − 6b','rc-math','middle')+text(411,187,'a','rc-math','middle')+line([[496,165],[565,165]],C.active,true)+rect(576,114,148,105)+text(650,153,'Next pair','rc-prose','middle')+text(650,188,(5*z.a-6*z.b)+', '+z.a,'rc-math','middle');b+=text(34,296,'State corresponds to index '+z.step+'; next pair is a preview.','rc-prose');}
 return svg(b);}
const why={conjugate:'Ferrers transposition is a cell-preserving involution relating row-count and largest-part constraints.',reflection:'Reflecting the first below-zero prefix maps bad balanced paths bijectively to paths ending at height two.',unrolling:'Each forcing contribution propagates through every subsequent multiplier; the exponent records that count.',differences:'A finite difference reduces a polynomial degree; the third row difference annihilates a quadratic.',boundary:'The recurrence starts at index three, leaving two independent prefix values before the tail.',tiling:'Every board is completely covered by disjoint dominoes; the first placement determines its recurrence case.',resonance:'Dividing by the forcing base exposes a constant second difference and the required quadratic index factor.',automaton:'The two aggregate states retain the suffix information needed for the forbidden-symbol rule.',derangements:'The two contributions are disjoint reversible cycle cases, each including the image choice.',partitions:'The insertion recurrence separates a singleton block from joining one of the existing blocks.',ferrers:'Removing a one and removing a complete column are different reversible operations.',catalan:'The first return gives a unique split into an enclosed path and a following path.',modular:'A complete pair, including the modulus, is an autonomous finite state; the first return establishes its cycle.',matrix:'The coordinate order and both previous values are required for the companion update.'};
function frameFormula(s,z,r){const n=z.step;
 if(s.operation==='conjugate')return '|'+r.original.join('+')+'|=|'+r.transposed.join('+')+'|='+r.total;
 if(s.operation==='reflection')return 'C_6=\\binom{12}{6}-\\binom{12}{7}=132';
 if(s.operation==='unrolling')return 'W_{'+n+'}='+z.sum;
 if(s.operation==='differences')return '\\Delta^{'+n+'}q(n)'+(n===2?'=2':n===3?'=0':'');
 if(s.operation==='boundary')return 'a_0=4,\\quad a_1=5,\\quad a_n=6\\cdot2^{n-2}\\quad(n\\ge2)';
 if(s.operation==='tiling'&&s.n===1)return 'T_1=1';
 if(s.operation==='tiling')return 'T_{'+s.n+'}=T_{'+(s.n-1)+'}+T_{'+(s.n-2)+'}='+r.vertical+'+'+r.horizontal+'='+r.count;
 if(s.operation==='resonance')return 'u_{'+n+'}=\\frac{'+n+'('+n+'-1)}{2},\\quad a_{'+n+'}='+z.value;
 if(s.operation==='automaton')return 'u_{n+1}=u_n+v_n,\\quad v_{n+1}=2u_n+v_n';
 if(s.operation==='derangements')return n<2?'D_{'+n+'}='+z.value:'D_{'+n+'}=('+n+'-1)(D_{'+(n-1)+'}+D_{'+(n-2)+'})='+z.value;
 if(s.operation==='partitions')return 'S(n,k)=S(n-1,k-1)+kS(n-1,k)';
 if(s.operation==='ferrers')return 'p('+s.n+',3)=p('+(s.n-1)+',2)+p('+(s.n-3)+',3)='+r.withOne+'+'+r.withoutOne+'='+r.count;
 if(s.operation==='catalan')return 'C_{'+s.n+'}=\\sum_{j=0}^{'+(s.n-1)+'}C_jC_{'+(s.n-1)+'-j}='+r.count;
 if(s.operation==='modular')return 'F_{'+n+'}\\equiv '+z.u+'\\pmod{'+s.modulus+'},\\quad F_{'+(n+1)+'}\\equiv '+z.v+'\\pmod{'+s.modulus+'}';
 return '(a_{'+n+'},a_{'+(n-1)+'})=('+z.a+','+z.b+')';
}
function operationText(s,z,r){
 if(s.operation==='unrolling')return z.step?'Add contribution '+z.terms.at(-1).value+' from injection index '+z.step+'; the accumulated sum becomes '+z.sum+'.':'Start with the initial value propagated to the target, equal to '+z.base+'.';
 if(s.operation==='differences')return z.step?'Subtract each earlier entry from its right neighbor to obtain difference order '+z.step+'.':'Read the quadratic sample row before taking any differences.';
 if(s.operation==='boundary')return z.step<3?'Retain the independently specified value at index '+z.step+'.':'Double the preceding tail value to obtain index '+z.step+'.';
 if(s.operation==='tiling')return z.step?'Inspect complete covering '+z.step+' and classify it by its first placement.':'Read the empty rectangular board before enumerating complete coverings.';
 if(s.operation==='resonance')return z.step<2?'Retain a normalized boundary value before the second-difference equation applies.':'The preceding two normalized values give the next value with constant second difference one.';
 if(s.operation==='automaton')return z.step===1?'Initialize each possible last-symbol count to one at length one.':'From preceding counts '+(z.v-z.u)+' and '+(2*z.u-z.v)+', update the restricted-ending count to '+z.u+' and the unrestricted-ending count to '+z.v+'.';
 if(s.operation==='derangements')return z.step<2?'Use the empty-permutation or one-element boundary, rather than an unavailable negative index.':'Combine '+z.two+' two-cycle cases and '+z.long+' longer-cycle cases after accounting for every image choice.';
 if(s.operation==='partitions')return z.step?'For each block count, combine a new singleton with insertion into one of the existing blocks.':'Initialize the unique empty partition in the zero-block column.';
 if(s.operation==='ferrers')return z.case+'; the right diagram shows its exact reduced partition.';
 if(s.operation==='catalan')return z.step?'Locate the first return at step '+z.split+' to separate the enclosed and following path.':'Begin enumeration of all valid nonnegative paths of the declared size.';
 if(s.operation==='conjugate')return z.step?'Swap every cell coordinate; the transposed diagram preserves the total cell count.':'Read the original row lengths before transposition.';
 if(s.operation==='reflection')return z.step?'Swap up and down steps only in the prefix through the first negative-one visit.':'Locate the first crossing below zero in a bad balanced path.';
 if(s.operation==='modular')return z.returnTo===undefined?'Replace the pair by its second residue and the sum of both residues, reduced modulo '+s.modulus+'.':'The complete starting pair returns, proving the displayed period of '+r.period+'.';
 return 'Multiply the latest term by five, subtract six times the preceding term, and shift the pair forward.';
}
function exactStateMath(s,z,r){const name=s.operation==='unrolling'?'W':['derangements'].includes(s.operation)?'D':s.operation==='partitions'?'B':s.operation==='resonance'?'a':s.operation==='automaton'||s.operation==='tiling'?'T':'a';let value=z.sum??z.value??z.total??z.bell??z.a??(z.values?.at(-1));if(s.operation==='tiling')return '<math xmlns="http://www.w3.org/1998/Math/MathML" display="inline"><mrow><msub><mi>T</mi><mn>'+s.n+'</mn></msub><mo>=</mo><mn>'+r.count+'</mn></mrow></math>';if(value===undefined)return '';return '<math xmlns="http://www.w3.org/1998/Math/MathML" display="inline"><mrow><msub><mi>'+name+'</mi><mn>'+z.step+'</mn></msub><mo>=</mo><mn>'+esc(value)+'</mn></mrow></math>';}
function makeModel(id,title,raw){const {spec:s,states,result:r}=evaluate(raw);return{id,title,kind:'exact-discrete',spec:s,result:r,invariant:why[s.operation],frames:states.map((z,i)=>({svg:draw(s,z,r),caption:'Checkpoint '+(i+1)+': '+s.operation+' state '+z.step,formula:frameFormula(s,z,r),formulaHtml:exactStateMath(s,z,r),snapshot:{step:i+1,state:copy(z),inputs:copy(s),result:i===states.length-1?copy(r):null},teaching:{currentState:'Declared index '+z.step,operation:operationText(s,z,r),why:why[s.operation],reading:'Use Before and Result to compare neighboring checkpoints; compare does not interpolate unknown states.',checks:[{mathHtml:'Input contract',result:'validated'},{mathHtml:'Trace domain',result:'finite exact model'}]}}))};}
if(typeof module!=='undefined')module.exports={makeModel,evaluate,validate,tilings,integerPartitions,dyck,binom,fact};
if(typeof document==='undefined')return;
function mount(host,m){if(!host.querySelector('.rc-controls')){const c=document.createElement('div');c.className='rc-controls';c.innerHTML='<button type="button" data-reset>Restart</button><button type="button" data-prev>Previous</button><button type="button" data-play>Play</button><button type="button" data-next>Next</button><label>Speed<select data-speed></select></label><label>Step<input type="range" data-seek min="0" value="0"></label>';host.querySelector('.rc-stage').before(c);}for(const cls of['rc-caption','rc-formula','rc-print'])if(!host.querySelector('.'+cls)){const e=document.createElement('div');e.className=cls;host.append(e);}return AdvancedSimulations.mount(host,m,{topic:'d_recurrence',prefix:'rc',retainDrawing:true});}
async function boot(){const data=await(await fetch('d_recurrence-models.json')).json();globalThis.RecurrencePlayers=[];for(const host of document.querySelectorAll('[data-rc-model]')){const m=data.models.find(m=>m.id===host.dataset.rcModel);if(!m)throw Error('Missing recurrence model');RecurrencePlayers.push(mount(host,m));}let active;const form=document.querySelector('#rc-form'),out=document.querySelector('#rc-output'),error=document.querySelector('#rc-error');form.addEventListener('submit',ev=>{ev.preventDefault();try{const f=form.elements,m=makeModel('editable-recurrence','Your exact recurrence model',{operation:f.operation.value,n:Number(f.n.value),p:Number(f.p.value),a0:Number(f.a0.value),modulus:Number(f.modulus.value)});active?.dispose();out.innerHTML='<section class="rc-model"><h3>'+esc(m.title)+'</h3><div class="rc-stage"></div></section><h3>Exact result</h3><pre>'+esc(JSON.stringify(m.result,null,2))+'</pre>';active=mount(out.firstChild,m);globalThis.RecurrenceLab=active;error.textContent='';}catch(e){error.textContent=e.message;}});form.dispatchEvent(new Event('submit',{cancelable:true}));}
boot().catch(e=>{document.querySelector('#rc-error').textContent=e.message;throw e;});
})();
